function updateClock() {
  var now = new Date();
  var time = now.toLocaleTimeString();
  document.getElementById('working-clock').textContent = time;
}

setInterval(updateClock, 1000);
updateClock();

var output = '';
for (var i = 1; i <= 5; i++) {
  output = output + i + ' ';
}
document.getElementById('loopForResult').textContent = output;

var num = 1;
while (num <= 100) {
  num = num * 2;
}
document.getElementById('loopWhileResult').textContent = num;

var total = 0;
var i = 1;
do {
  total = total + i;
  i = i + 1;
} while (total < 10);

document.getElementById('loopDoWhileResult').textContent = total;

var fruits = ['Apple', 'Banana', 'Cherry'];
var output = '';
for (var fruit of fruits) {
  output = output + fruit + ' ';
}
document.getElementById('loopForOfResult').textContent = output;

var person = { name: 'Alex', age: 25, city: 'Miami' };
var output = '';
for (var key in person) {
  output = output + key + ' ';
}
document.getElementById('loopForInResult').textContent = output;
